import{_ as t,c as s,o as a,ah as r,j as e,a as n}from"./chunks/framework.CAZQ2vdu.js";const o="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_select.jpg",d="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_trench_selection.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_canvas.jpg",c="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_canvas_detail.jpg",u="/Qonnectra-docs/pr-17/videos/pipe_branch_connect.webm",g="/Qonnectra-docs/pr-17/videos/pipe_branch_auto_connect.webm",b="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_auto_connect.jpg",m="/Qonnectra-docs/pr-17/images/manual/teil-a/pipe_branch_controls.jpg",A=JSON.parse('{"title":"12. Rohrverzweigung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/12-rohrverzweigung.md","filePath":"manual/teil-a-anwenderhandbuch/12-rohrverzweigung.md"}'),p={name:"manual/teil-a-anwenderhandbuch/12-rohrverzweigung.md"};function f(k,i,w,v,z,_){return a(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="_12-rohrverzweigung" tabindex="-1">12. Rohrverzweigung <a class="header-anchor" href="#_12-rohrverzweigung" aria-label="Permalink to &quot;12. Rohrverzweigung&quot;">​</a></h1><p>An einem Rohrabzweig treffen mehrere Rohre aufeinander, und die Mikrorohre des einen setzen sich in denen eines anderen fort. Die <strong>Rohrverzweigung</strong> hält diese Übergänge fest: Sie verbinden darin Mikrorohr für Mikrorohr und dokumentieren so, welcher Weg an dieser Stelle weiterführt. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Verzweigung“.</p><p><img src="'+o+'" alt="Screenshot der Rohrverzweigung mit dem Bereich „Eigenschaften“ oben links und der noch leeren Arbeitsfläche" data-zoomable="true"></p><p>Den größten Teil der Ansicht nimmt die <strong>Arbeitsfläche</strong> ein. Sie ist ein Diagramm und keine Karte: Wo ein Rohr darin liegt, hat mit seiner Lage im Gelände nichts zu tun. Oben links steht der Bereich „Eigenschaften“ mit der Auswahl der Rohrverzweigung, unten links die Schaltflächen zum Zoomen und Sperren, siehe Abschnitt <a href="#_12-4-arbeitsflache-anordnen-zoomen-sperren">Arbeitsfläche</a>.</p><p>Der Weg durch diese Ansicht ist immer derselbe: Netzknoten auswählen, Trassen und Rohre auf die Arbeitsfläche laden, Mikrorohre verbinden.</p><h2 id="_12-1-rohrverzweigung-auswahlen" tabindex="-1">12.1 Rohrverzweigung auswählen <a class="header-anchor" href="#_12-1-rohrverzweigung-auswahlen" aria-label="Permalink to &quot;12.1 Rohrverzweigung auswählen&quot;">​</a></h2><p>Im Feld „Rohrverzweigung auswählen“ stehen die Netzknoten des Projekts, die als Rohrabzweig infrage kommen. Welche das sind, legt Ihre Administration fest, siehe Abschnitt <a href="#_12-5-voraussetzung-konfigurierte-rohrabzweig-einstellungen">Voraussetzung</a>.</p><p><img src="'+h+'" alt="Screenshot der Rohrverzweigung mit Hervorhebung des Feldes „Rohrverzweigung auswählen“ und der geöffneten Liste der Netzknoten oben links" data-zoomable="true"></p><p>Mit der Auswahl sucht Qonnectra alle Trassen, die höchstens fünf Meter vom Netzknoten entfernt liegen, und öffnet damit sofort das Fenster „Trassen auswählen“, siehe den nächsten Abschnitt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Findet Qonnectra in diesem Umkreis keine Trasse, meldet es „Keine Trassen in der Nähe dieses Netzknotens gefunden“, und die Arbeitsfläche bleibt leer. Prüfen Sie in der Karte, ob die Trassen tatsächlich am Netzknoten enden – die fünf Meter lassen sich nicht einstellen.</p></div><h2 id="_12-2-grabenauswahl-bearbeiten" tabindex="-1">12.2 Grabenauswahl bearbeiten <a class="header-anchor" href="#_12-2-grabenauswahl-bearbeiten" aria-label="Permalink to &quot;12.2 Grabenauswahl bearbeiten&quot;">​</a></h2><p>Das Fenster „Trassen auswählen“ bestimmt, was auf der Arbeitsfläche landet. Unter der Überschrift steht, wie viele Trassen gefunden wurden und wie viele Rohre davon derzeit ausgewählt sind.</p><p>Jede Trasse steht mit ihrer Trassen-ID in einer eigenen Zeile, darunter die Zahl ihrer ausgewählten Rohre („1/2 Rohr“). Klappen Sie eine Trasse auf, sehen Sie ihre Rohre einzeln, jedes mit der Zahl seiner Mikrorohre. Das Kästchen vor der Trassen-ID wählt alle Rohre einer Trasse auf einmal, die Schaltflächen „Alle auswählen“ und „Keine auswählen“ oben rechts alle Rohre aller Trassen.</p><p><img src="'+d+'" alt="Screenshot der Rohrverzweigung mit Hervorhebung des Fensters „Trassen auswählen“ mit aufgeklappten Trassen oben links" data-zoomable="true"></p><p>Rohre, die an diesem Netzknoten bereits Mikrorohrverbindungen haben, sind mit „Hat Verbindungen“ gekennzeichnet, von vornherein ausgewählt und mit einem Schloss gesperrt. Sie lassen sich nicht abwählen – sonst blieben gespeicherte Verbindungen ohne Gegenstück auf der Arbeitsfläche.</p><p>„Auf Canvas laden“ übernimmt die Auswahl auf die Arbeitsfläche. „Abbrechen“ verwirft nicht nur die Auswahl, sondern auch den Netzknoten; Sie beginnen dann wieder mit Abschnitt <a href="#_12-1-rohrverzweigung-auswahlen">Rohrverzweigung auswählen</a>. Solange ein Netzknoten ausgewählt ist, öffnet die Schaltfläche „Grabenauswahl bearbeiten“ das Fenster erneut.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Fenster spricht von „Trassen“, die Schaltfläche daneben von der „Grabenauswahl“. Gemeint ist beides Mal dasselbe: die Trassen rund um den Netzknoten.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Qonnectra meldet „Trassenauswahl erfolgreich gespeichert“, merkt sich die Auswahl aber nicht. Kehren Sie später zu demselben Netzknoten zurück, ist wieder nur ausgewählt, was dort bereits Verbindungen hat; die übrigen Rohre stellen Sie erneut zusammen. Verloren geht dabei nichts – die gespeicherten Mikrorohrverbindungen bleiben erhalten. Das Speichern der Auswahl setzt Rechte voraus, die keine der mitgelieferten Rollen enthält, siehe Kapitel <a href="./../teil-b-betrieb-admin-qgis/19-rollen-und-rechte.html">Rollen und Rechte</a>.</p></div><h2 id="_12-3-mikrorohre-verbinden-und-auto-verbindung" tabindex="-1">12.3 Mikrorohre verbinden und Auto-Verbindung <a class="header-anchor" href="#_12-3-mikrorohre-verbinden-und-auto-verbindung" aria-label="Permalink to &quot;12.3 Mikrorohre verbinden und Auto-Verbindung&quot;">​</a></h2><p>Jedes geladene Rohr erscheint als Kreis auf der Arbeitsfläche. Der Kasten daneben nennt die Trassen-ID, den Namen des Rohrs und die Zahl seiner Mikrorohre. Auf dem Kreis liegen die Mikrorohre als farbige Punkte untereinander, von oben nach unten in der Reihenfolge ihrer Nummern.</p><p class="img-row"><img src="'+l+'" alt="Screenshot der Rohrverzweigung mit fünf Rohren als Kreise auf der Arbeitsfläche" data-zoomable="true"><img src="'+c+'" alt="Ausschnitt eines Rohrs auf der Arbeitsfläche mit seinen Mikrorohren als farbige Punkte" data-zoomable="true"></p><p>Zeigen Sie auf einen Punkt, nennt der Hinweis Rohr, Nummer und Farbe des Mikrorohrs. Er ist englisch beschriftet, etwa „St-VL-01 - Microduct 3 (blau)“.</p><p>Mikrorohre mit einem Status – etwa „Defekt“, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-4-mikrorohre-eines-rohrs">Mikrorohre eines Rohrs</a> – sind blass gezeichnet und tragen ein Kreuz.</p><h3 id="_12-3-1-einzelne-mikrorohre-verbinden" tabindex="-1">12.3.1 Einzelne Mikrorohre verbinden <a class="header-anchor" href="#_12-3-1-einzelne-mikrorohre-verbinden" aria-label="Permalink to &quot;12.3.1 Einzelne Mikrorohre verbinden&quot;">​</a></h3><p>Ziehen Sie mit gedrückter linker Maustaste vom Punkt des einen Mikrorohrs zum Punkt des anderen. Zwischen beiden entsteht eine Linie, beschriftet mit den beiden Nummern („5 ↔ 5“) und einem roten Kreuz zum Löschen.</p>',25),e("p",null,[e("video",{src:u,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/pipe_branch_connect.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Die Verbindung ist mit dem Loslassen gespeichert, Qonnectra bestätigt mit „Verbindung erfolgreich erstellt“. Einen „Speichern“-Button gibt es nicht.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Ein Mikrorohr lässt sich nicht mit sich selbst verbinden; Qonnectra meldet dann „Mikrorohr kann nicht mit sich selbst verbunden werden“. Das betrifft auch den Fall, dass dasselbe Rohr über zwei Trassen auf die Arbeitsfläche gelangt ist: Beide Kreise zeigen dieselben Mikrorohre.</p></div><h3 id="_12-3-2-auto-verbindung" tabindex="-1">12.3.2 Auto-Verbindung <a class="header-anchor" href="#_12-3-2-auto-verbindung" aria-label="Permalink to &quot;12.3.2 Auto-Verbindung&quot;">​</a></h3><p>Der Umschalter „Auto-Verbindung“ verbindet zwei Rohre auf einmal – jedes Mikrorohr mit dem Mikrorohr derselben Nummer im anderen Rohr.</p><ol><li>Schalten Sie „Auto-Verbindung“ ein.</li><li>Umkreisen Sie mit gedrückter linker Maustaste die beiden Kreise, die Sie verbinden wollen. Der Bereich „Eigenschaften“ zeigt darauf „Ausgewählt: 2 Netzknoten“.</li><li>Klicken Sie auf „Ausgewählte Netzknoten verbinden“.</li></ol>',5),e("p",null,[e("video",{src:g,controls:"",playsinline:"",preload:"metadata"},[n(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/pipe_branch_auto_connect.webm",download:""},"herunterladen"),n(" anstelle des Videos. ")])],-1),r('<p>Verbunden wird jedes Paar gleicher Nummer, das noch nicht verbunden ist. Qonnectra meldet anschließend die Zahl der neuen Verbindungen, etwa „7x Verbindungen erfolgreich erstellt“.</p><p><img src="'+b+'" alt="Screenshot der Rohrverzweigung mit Hervorhebung des Umschalters „Auto-Verbindung“ und der Schaltfläche „Ausgewählte Netzknoten verbinden“ oben links" data-zoomable="true"></p><p>„Auswahl löschen“ hebt die Auswahl wieder auf. Haben Sie mehr als zwei Kreise umkreist, steht statt der Schaltfläche der Hinweis „Bitte wählen Sie genau 2 Netzknoten aus“.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Solange „Auto-Verbindung“ eingeschaltet ist, liegt eine Zeichenfläche über der Arbeitsfläche: Einzelne Mikrorohre lassen sich nicht mehr anklicken, und den Ausschnitt verschieben Sie nur noch mit der mittleren Maustaste. Das Mausrad zoomt weiterhin. Schalten Sie den Umschalter aus, wenn Sie wieder einzeln verbinden wollen.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Haben die beiden Rohre keine Nummer gemeinsam oder sind alle Paare schon verbunden, meldet Qonnectra „Keine passenden Mikrorohre für die Verbindung verfügbar“ und ändert nichts.</p></div><h3 id="_12-3-3-verbindung-loschen" tabindex="-1">12.3.3 Verbindung löschen <a class="header-anchor" href="#_12-3-3-verbindung-loschen" aria-label="Permalink to &quot;12.3.3 Verbindung löschen&quot;">​</a></h3><p>Das rote Kreuz an der Beschriftung einer Verbindung löscht sie. Gelöscht wird dabei nur die Verbindung – die beiden Mikrorohre bleiben erhalten.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Das Löschen erfolgt ohne Rückfrage.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das Löschen setzt die Zugriffsstufe „Vollzugriff“ voraus; die Berechtigung zum Bearbeiten genügt dafür nicht. Fehlt sie, verschwindet die Verbindung zwar von der Arbeitsfläche, und Qonnectra meldet „Verbindung erfolgreich gelöscht“ – gelöscht ist sie damit aber nicht. Laden Sie den Netzknoten erneut, ist sie wieder da. Wenden Sie sich in diesem Fall an Ihre Administration.</p></div><h2 id="_12-4-arbeitsflache-anordnen-zoomen-sperren" tabindex="-1">12.4 Arbeitsfläche: Anordnen, Zoomen, Sperren <a class="header-anchor" href="#_12-4-arbeitsflache-anordnen-zoomen-sperren" aria-label="Permalink to &quot;12.4 Arbeitsfläche: Anordnen, Zoomen, Sperren&quot;">​</a></h2><p>Unten links liegen vier Schaltflächen: hineinzoomen, herauszoomen, alles einpassen und das Schloss. Ihre Hinweise sind englisch beschriftet („Zoom In“, „Zoom Out“, „Fit View“, „Toggle Interactivity“).</p><p><img src="'+m+'" alt="Screenshot der Rohrverzweigung mit Hervorhebung der Schaltflächen zum Zoomen und Sperren unten links" data-zoomable="true"></p><p>Beim Öffnen ist die Arbeitsfläche <strong>gesperrt</strong>: Das Schloss ist geschlossen, und die Kreise lassen sich nicht verschieben. Ein Klick auf das Schloss hebt die Sperre auf – danach ziehen Sie die Kreise an eine Stelle, an der sich die Verbindungen gut lesen lassen.</p><p>Den Ausschnitt verschieben, mit dem Mausrad zoomen und Mikrorohre verbinden können Sie in beiden Zuständen; die Sperre betrifft nur das Verschieben und Auswählen der Kreise.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Anordnung der Kreise wird nicht gespeichert. Laden Sie den Netzknoten erneut, liegen sie wieder gleichmäßig verteilt auf einem großen Kreis.</p></div><h2 id="_12-5-voraussetzung-konfigurierte-rohrabzweig-einstellungen" tabindex="-1">12.5 Voraussetzung: konfigurierte Rohrabzweig-Einstellungen <a class="header-anchor" href="#_12-5-voraussetzung-konfigurierte-rohrabzweig-einstellungen" aria-label="Permalink to &quot;12.5 Voraussetzung: konfigurierte Rohrabzweig-Einstellungen&quot;">​</a></h2><p>Welche Netzknoten im Feld „Rohrverzweigung auswählen“ stehen, ergibt sich aus den <strong>Rohrabzweig-Einstellungen</strong> des Projekts. Ihre Administration legt dort die Netzknotentypen fest, die als Rohrabzweig gelten; eingerichtet werden sie in Kapitel <a href="./../teil-b-betrieb-admin-qgis/22-projektbezogene-konfiguration.html">Projektbezogene Konfiguration</a>.</p><p>Fehlen die Einstellungen, arbeitet die Ansicht trotzdem – die Auswahl enthält dann aber jeden Netzknoten des Projekts, und über dem Feld steht „Rohrabzweig-Einstellungen für dieses Projekt nicht konfiguriert.“ Bei vielen Netzknoten wird die Suche nach dem richtigen dadurch mühsam.</p>',18)])])}const R=t(p,[["render",f]]);export{A as __pageData,R as default};
